/* ── Component: ImageCard ──────────────────────────────────────── */
function ImageCard({ id, src, alt, name, size, dimensions, onDeleteRequest }) {
  return `
    <article class="card" id="card-${id}">
      <div class="card__thumb">
        <img src="${src}" alt="${alt}" loading="lazy" />
        <span class="card__badge" aria-hidden="true">${dimensions}</span>
      </div>
      <div class="card__body">
        <p class="card__name" title="${name}">${name}</p>
        <p class="card__meta">
          <span>${size}</span>
          <span>${dimensions}</span>
        </p>
      </div>
      <div class="card__actions">
        <button
          class="btn-icon btn-icon--ghost"
          type="button"
          aria-label="Download ${name}"
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none"
               aria-hidden="true" focusable="false">
            <path d="M8 1v9M4 7l4 4 4-4M2 13h12"
                  stroke="currentColor" stroke-width="1.6"
                  stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
          Download
        </button>
        <button
          class="btn-icon btn-icon--danger trigger"
          type="button"
          data-image-id="${id}"
          data-image-name="${name}"
          data-image-src="${src}"
          data-image-alt="${alt}"
          aria-label="Delete ${name}"
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none"
               aria-hidden="true" focusable="false">
            <path d="M2 4h12M5 4V2h6v2M6 7v5M10 7v5M3 4l1 9h8l1-9"
                  stroke="currentColor" stroke-width="1.6"
                  stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
          Delete
        </button>
      </div>
    </article>
  `;
}

/* ── Component: DeleteConfirmDialog ───────────────────────────── */
function DeleteConfirmDialog() {
  return `
    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-desc">
      <div class="dialog__header">
        <div class="dialog__icon-wrap" aria-hidden="true">
          <svg width="18" height="18" viewBox="0 0 16 16" fill="none"
               focusable="false">
            <path d="M2 4h12M5 4V2h6v2M6 7v5M10 7v5M3 4l1 9h8l1-9"
                  stroke="currentColor" stroke-width="1.6"
                  stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </div>
        <div>
          <h2 class="dialog__title" id="dialog-title">Delete image?</h2>
        </div>
      </div>

      <div class="dialog__preview" id="dialog-preview-wrap">
        <img id="dialog-preview-img" src="" alt="" />
      </div>

      <div class="dialog__body">
        <p id="dialog-desc">
          You're about to permanently delete
          <strong id="dialog-image-name"></strong>
          from your library.
        </p>
        <div class="dialog__warning" role="note">
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none"
               aria-hidden="true" focusable="false">
            <path d="M8 1L1 14h14L8 1z" stroke="currentColor"
                  stroke-width="1.5" stroke-linejoin="round"/>
            <path d="M8 6v4M8 12v.5"
                  stroke="currentColor" stroke-width="1.6"
                  stroke-linecap="round"/>
          </svg>
          This action cannot be undone.
        </div>
      </div>

      <div class="dialog__footer">
        <button class="btn btn--cancel" type="button" id="cancel-btn">
          Cancel
        </button>
        <button class="btn btn--delete" type="button" id="confirm-delete-btn">
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none"
               aria-hidden="true" focusable="false">
            <path d="M2 4h12M5 4V2h6v2M6 7v5M10 7v5M3 4l1 9h8l1-9"
                  stroke="currentColor" stroke-width="1.6"
                  stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
          Delete image
        </button>
      </div>
    </dialog>
  `;
