const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  // Build a single-file version so Playwright can load it with all assets inlined
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('styles.css',  'utf8');
  const js   = fs.readFileSync('app.js',       'utf8');

  const combined = html
    .replace('<link rel=\"stylesheet\" href=\"styles.css\" />', '<style>' + css + '</style>')
    .replace('<script src=\"app.js\"></script>', '<script>' + js + '</script>');

  const b    = await chromium.launch();
  const page = await b.newPage();
  await page.setContent(combined, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  const r = await page.evaluate('async () => await window.axe.run()');

  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));

  // Also test with dialog open
  await page.evaluate(() => {
    document.querySelector('.trigger').click();
  });
  await page.waitForTimeout(300);
  const r2   = await page.evaluate('async () => await window.axe.run()');
  const wcag2 = r2.violations.filter(v => !v.tags.includes('best-practice'));
  const bp2   = r2.violations.filter(v =>  v.tags.includes('best-practice'));

  await b.close();

  console.log(JSON.stringify({
    closed: {
      wcag: wcag.map(v => ({ id: v.id, impact: v.impact, desc: v.description, targets: v.nodes.map(n => n.target) })),
      bp:   bp.map(v =>   ({ id: v.id, targets: v.nodes.map(n => n.target) })),
    },
    open: {
      wcag: wcag2.map(v => ({ id: v.id, impact: v.impact, desc: v.description, targets: v.nodes.map(n => n.target) })),
      bp:   bp2.map(v =>   ({ id: v.id, targets: v.nodes.map(n => n.target) })),
    },
  }, null, 2));

  process.exit((wcag.length + wcag2.length) > 0 ? 1 : 0);
})().catch(e => { console.error(e.message); process.exit(2); });
