  page.on('console', m => { if (m.type() === 'error') console.error('PAGE ERR:', m.text()); });
  page.on('pageerror', e => console.error('PAGE CRASH:', e.message));

  await page.setContent(combined, { waitUntil: 'domcontentloaded' });
