(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('styles.css',  'utf8');
  const js   = fs.readFileSync('app.js',       'utf8');

  const combined = html
    .replace('<link rel=\"stylesheet\" href=\"styles.css\" />', '<style>' + css + '</style>')
    .replace('<script src=\"app.js\"></script>', '<script>' + js + '</script>');

  const b    = await chromium.launch();
  const page = await b.newPage();
  await page.setContent(combined, { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(500);
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  await page.waitForTimeout(300);

  // Run with dialog closed
  const r1 = await page.evaluate(async () => await window.axe.run());

  // Open dialog, re-test
  await page.evaluate(() => document.querySelector('.trigger').click());
  await page.waitForTimeout(400);
  const r2 = await page.evaluate(async () => await window.axe.run());

  await b.close();

  function fmt(r) {
    const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
    const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
    return {
      wcag: wcag.map(v => ({ id: v.id, impact: v.impact, desc: v.description, targets: v.nodes.map(n => ({t: n.target, html: n.html, fix: n.failureSummary})) })),
      bp:   bp.map(v =>   ({ id: v.id, targets: v.nodes.map(n => n.target) })),
    };
  }

  const out = { closed: fmt(r1), open: fmt(r2) };
  console.log(JSON.stringify(out, null, 2));
  const totalWcag = out.closed.wcag.length + out.open.wcag.length;
  process.exit(totalWcag > 0 ? 1 : 0);
})().catch(e => { console.error('FATAL:', e.message); process.exit(2); });
