  --clr-cancel-bg:   rgba(124, 130, 160, 0.12);
  --radius-sm:       6px;
  --radius-md:       12px;
  --radius-lg:       16px;
  --shadow-card:     0 4px 24px rgba(0,0,0,.4);
  --shadow-dialog:   0 24px 80px rgba(0,0,0,.65);
  --transition:      160ms ease;
  --font:            'Inter', system-ui, -apple-system, sans-serif;
}

/* ── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 0;
  padding: .5rem 1rem;
  background: var(--clr-accent);
  color: #fff;
  font-weight: 600;
  z-index: 9999;
  border-radius: 0 0 var(--radius-sm) 0;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Base ─────────────────────────────────────────────────────── */
body {
  font-family: var(--font);
  background: var(--clr-bg);
  color: var(--clr-text);
  min-height: 100vh;
  line-height: 1.5;
}

/* ── Layout ───────────────────────────────────────────────────── */
.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2rem;
  border-bottom: 1px solid var(--clr-border);
  background: var(--clr-surface);
  position: sticky;
  top: 0;
  z-index: 10;
}

.site-logo {
  display: flex;
  align-items: center;
  gap: .6rem;
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--clr-text);
  text-decoration: none;
}
.site-logo svg { color: var(--clr-accent); flex-shrink: 0; }

.site-header nav { display: flex; gap: .25rem; }
.nav-link {
  padding: .4rem .85rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 500;
  color: var(--clr-text-muted);
  text-decoration: none;
  transition: background var(--transition), color var(--transition);
}
.nav-link:hover, .nav-link:focus-visible {
  background: var(--clr-surface-2);
  color: var(--clr-text);
}
.nav-link.active { color: var(--clr-text); }
.nav-link:focus-visible { outline: 2px solid var(--clr-accent); outline-offset: 2px; }

main {
  max-width: 1100px;
  margin: 0 auto;
  padding: 2.5rem 2rem 4rem;
}

/* ── Page heading row ─────────────────────────────────────────── */
.page-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 2rem;
  gap: 1rem;
  flex-wrap: wrap;
}
.page-header h1 { font-size: 1.6rem; font-weight: 700; }
.page-header p  { color: var(--clr-text-muted); font-size: .875rem; margin-top: .25rem; }

.upload-btn {
  display: inline-flex;
  align-items: center;
  gap: .45rem;
  padding: .55rem 1.1rem;
  background: var(--clr-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
  white-space: nowrap;
}
.upload-btn:hover  { background: var(--clr-accent-h); }
.upload-btn:focus-visible {
  outline: 2px solid var(--clr-accent);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px rgba(124, 109, 245, .25);
}

/* ── Gallery grid ─────────────────────────────────────────────── */
.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.25rem;
}

/* ── Image card ───────────────────────────────────────────────── */
.card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition), box-shadow var(--transition);
}
.card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 32px rgba(0,0,0,.55);
}

.card__thumb {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
  background: var(--clr-surface-2);
}
.card__thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 300ms ease;
}
.card:hover .card__thumb img { transform: scale(1.04); }

.card__badge {
  position: absolute;
  top: .6rem;
  right: .6rem;
  background: rgba(10, 12, 20, .7);
  backdrop-filter: blur(6px);
  border-radius: 4px;
  padding: .2rem .5rem;
  font-size: .7rem;
  font-weight: 600;
  color: var(--clr-text-muted);
  pointer-events: none;
}

.card__body {
  padding: .85rem 1rem;
  display: flex;
  flex-direction: column;
  gap: .5rem;
}
.card__name {
  font-size: .875rem;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.card__meta {
  font-size: .75rem;
  color: var(--clr-text-muted);
  display: flex;
  gap: .75rem;
}

.card__actions {
  display: flex;
  gap: .5rem;
  padding: 0 1rem 1rem;
}

.btn-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .4rem;
  padding: .45rem .85rem;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  font-size: .8rem;
  font-weight: 500;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  background: transparent;
  color: var(--clr-text-muted);
}
.btn-icon:focus-visible {
  outline: 2px solid var(--clr-accent);
  outline-offset: 2px;
}

.btn-icon--ghost {
  border-color: var(--clr-border);
  color: var(--clr-text-muted);
}
.btn-icon--ghost:hover {
  background: var(--clr-surface-2);
  color: var(--clr-text);
  border-color: var(--clr-surface-2);
}

.btn-icon--danger {
  border-color: transparent;
  color: var(--clr-danger);
}
.btn-icon--danger:hover {
  background: var(--clr-danger-bg);
  border-color: rgba(224,82,82,.25);
}

/* ── Modal dialog ─────────────────────────────────────────────── */
dialog {
  position: fixed;
  inset: 0;
  margin: auto;
  width: min(440px, calc(100vw - 2rem));
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  padding: 0;
  box-shadow: var(--shadow-dialog);
  color: var(--clr-text);
  max-height: calc(100vh - 2rem);
  overflow-y: auto;
}
dialog::backdrop {
  background: rgba(5, 6, 12, .75);
  backdrop-filter: blur(4px);
}

/* Entry animation */
@media (prefers-reduced-motion: no-preference) {
  dialog[open] {
    animation: dialog-in 200ms ease forwards;
  }
  @keyframes dialog-in {
    from { opacity: 0; transform: translateY(10px) scale(.97); }
    to   { opacity: 1; transform: none; }
  }
}

.dialog__header {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.5rem 1.5rem 1rem;
}
.dialog__icon-wrap {
  flex-shrink: 0;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  background: var(--clr-danger-bg);
  border: 1px solid rgba(224,82,82,.25);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--clr-danger);
}

.dialog__title {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: .25rem;
  padding-top: .3rem;
}

.dialog__preview {
  margin: 0 1.5rem .25rem;
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 1px solid var(--clr-border);
  aspect-ratio: 16/7;
}
.dialog__preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.dialog__body {
  padding: .75rem 1.5rem 1.25rem;
}
.dialog__body p {
  font-size: .9rem;
  color: var(--clr-text-muted);
  line-height: 1.65;
}
.dialog__body strong { color: var(--clr-text); font-weight: 600; }

.dialog__warning {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-top: .85rem;
  padding: .65rem .85rem;
  background: var(--clr-danger-bg);
  border: 1px solid rgba(224,82,82,.2);
  border-radius: var(--radius-sm);
  font-size: .8rem;
  color: var(--clr-danger);
}

.dialog__footer {
  display: flex;
  justify-content: flex-end;
  gap: .6rem;
  padding: 1rem 1.5rem 1.5rem;
  border-top: 1px solid var(--clr-border);
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .55rem 1.15rem;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  font-size: .875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
}
.btn:focus-visible {
  outline: 2px solid var(--clr-accent);
  outline-offset: 3px;
}

.btn--cancel {
  background: var(--clr-cancel-bg);
  border-color: var(--clr-border);
  color: var(--clr-text);
}
.btn--cancel:hover { background: var(--clr-surface-2); }

.btn--delete {
  background: var(--clr-danger);
  color: #fff;
}
.btn--delete:hover { background: var(--clr-danger-h); }
.btn--delete:focus-visible { outline-color: var(--clr-danger); }

/* ── Forced colors / high-contrast ───────────────────────────── */
@media (forced-colors: active) {
  .btn--delete { forced-color-adjust: none; }
  .dialog__icon-wrap { border: 2px solid ButtonText; }
}

/* ── Reflow / narrow viewports ────────────────────────────────── */
@media (max-width: 480px) {
  .site-header { padding: .75rem 1rem; }
  main { padding: 1.5rem 1rem 3rem; }
  .gallery { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
  .dialog__footer { flex-direction: column-reverse; }
  .dialog__footer .btn { width: 100%; justify-content: center; }
}

@media (max-width: 360px) {
  .site-header nav { display: none; }
}
